func:
// Este nodo lee la ultima respuesta y decide si el bucle sigue o termina.
// El modelo marca con el simbolo de tilde verde cuando considera que ya esta.
// Pedimos al menos dos vueltas: la primera es un borrador, la segunda la mejora.

const mensajes = msg.state.messages || [];
let respuestas = 0;
let ultima = null;

for (const m of mensajes) {
    const tipo = m && (m.type || m.role);
    if (tipo === "ai" || tipo === "assistant") {
        respuestas++;
        ultima = m;
    }
}

const contenido = ultima ? (ultima.data ? ultima.data.content : ultima.content) : "";
const texto = typeof contenido === "string" ? contenido : JSON.stringify(contenido || "");

if (respuestas >= 2 && texto.indexOf("✅") !== -1) {
    // Ya esta listo: sacamos la marca para que la respuesta final quede limpia.
    const limpio = texto.replace(/✅/g, "").trim();
    if (ultima.data) { ultima.data.content = limpio; } else { ultima.content = limpio; }
    msg.state.next_node = "end";
    node.status({ fill: "green", shape: "dot", text: "criterio cumplido" });
} else if (respuestas >= 2) {
    // Ya hubo mejora, pero el modelo no marco el final: otra vuelta.
    msg.state.next_node = "llm";
    node.status({ fill: "yellow", shape: "dot", text: "falta la marca" });
} else {
    // Primera respuesta: siempre dejamos que haya una segunda.
    msg.state.next_node = "llm";
    node.status({ fill: "grey", shape: "dot", text: "borrador" });
}

return msg;

// Recibe un pedido como { name: "clima", input: "Ciudad, País" }.
// Si no hay ciudad, respondemos sin llamar a ningún servicio.
const pedido = msg.payload || {};
const texto = String(pedido.input || "").trim();

if (!texto) {
    msg.payload = { output: "Necesito una ciudad. Probá con: Rosario, Argentina." };
    node.status({ fill: "red", shape: "ring", text: "falta ciudad" });
    return [msg, null];
}

// "Rosario, Santa Fe, Argentina" -> ciudad "Rosario", país "Argentina".
// Si no se indica país, asumimos Argentina.
const partes = texto.split(",").map(function (p) { return p.trim(); }).filter(Boolean);
const ciudad = partes[0];
const pais = partes.length > 1 ? partes[partes.length - 1] : "Argentina";

msg._busqueda = { ciudad: ciudad, pais: pais, paisExplicito: partes.length > 1 };
msg.url = "https://geocoding-api.open-meteo.com/v1/search?name=" +
    encodeURIComponent(ciudad) + "&count=10&language=es&format=json";
msg.requestTimeout = 6000;

node.status({ fill: "blue", shape: "ring", text: "buscando " + ciudad });
return [null, msg];

// Open-Meteo devuelve una lista de lugares con ese nombre.
// Elegimos el que coincide con el país pedido.
const busqueda = msg._busqueda || {};
const datos = msg.payload || {};

function normalizar(t) {
    return String(t || "").toLowerCase().normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/[^a-z0-9 ]/g, "")
        .replace(/\s+/g, " ")
        .trim();
}

// El modelo a veces escribe el país en inglés ("Spain") y Open-Meteo
// responde en español ("España"). Estos alias evitan ese choque.
const ALIAS_PAIS = {
    "spain": "espana",
    "france": "francia",
    "italy": "italia",
    "germany": "alemania",
    "united kingdom": "reino unido",
    "great britain": "reino unido",
    "uk": "reino unido",
    "united states": "estados unidos",
    "united states of america": "estados unidos",
    "usa": "estados unidos",
    "us": "estados unidos",
    "eeuu": "estados unidos",
    "brazil": "brasil",
    "mexico": "mexico",
    "peru": "peru",
    "japan": "japon",
    "russia": "rusia",
    "canada": "canada",
    "netherlands": "paises bajos",
    "belgium": "belgica",
    "switzerland": "suiza",
    "sweden": "suecia",
    "norway": "noruega",
    "denmark": "dinamarca",
    "ireland": "irlanda",
    "poland": "polonia",
    "greece": "grecia",
    "turkey": "turquia",
    "egypt": "egipto",
    "south africa": "sudafrica",
    "new zealand": "nueva zelanda"
};

if (msg.statusCode && msg.statusCode >= 400) {
    msg.payload = {
        output: "El servicio del clima no está disponible ahora (" +
            msg.statusCode + "). Probá de nuevo en unos minutos."
    };
    node.status({ fill: "red", shape: "ring", text: "servicio " + msg.statusCode });
    return [msg, null];
}

const resultados = Array.isArray(datos.results) ? datos.results : [];

if (resultados.length === 0) {
    msg.payload = {
        output: 'No encontré "' + busqueda.ciudad +
            '". Revisá el nombre o probá con "Ciudad, País".'
    };
    node.status({ fill: "grey", shape: "ring", text: "sin resultados" });
    return [msg, null];
}

const paisBuscado = normalizar(busqueda.pais);
const paisEsperado = ALIAS_PAIS[paisBuscado] || paisBuscado;
const encontrados = resultados.filter(function (r) {
    return normalizar(r.country) === paisEsperado ||
        String(r.country_code || "").toLowerCase() ===
            String(busqueda.pais || "").toLowerCase();
});

let lugar = encontrados[0];

// Si no se indicó país y la ciudad no está en el país por defecto,
// usamos el resultado más relevante del mundo. Así funciona también
// cuando el modelo manda solo "Madrid" o "París".
if (!lugar && !busqueda.paisExplicito) {
    lugar = resultados[0];
}

if (!lugar) {
    // Ayudamos a corregir: mostramos dónde sí existe ese nombre.
    const opciones = resultados.slice(0, 3).map(function (r) {
        return r.name + " (" + r.country + ")";
    });
    msg.payload = {
        output: 'No encontré "' + busqueda.ciudad + '" en ' + busqueda.pais +
            ". Sí encontré: " + opciones.join(", ") +
            '. Probá con "Ciudad, País".'
    };
    node.status({ fill: "grey", shape: "ring", text: "no está en " + busqueda.pais });
    return [msg, null];
}

// Limpiamos el nombre de la provincia/región para que la frase no quede
// interminable. Si es igual al nombre de la ciudad, no lo repetimos.
function limpiarAdmin(t) {
    return String(t || "")
        .replace(/^(Provincia de|Comunidad Autónoma de|Comunidad de|Región de|Estado de|Departamento de)\s+/i, "")
        .split(",")[0]
        .trim();
}
const admin = limpiarAdmin(lugar.admin1);
const detalle = admin && normalizar(admin) !== normalizar(lugar.name) ? ", " + admin : "";
msg._lugar = {
    etiqueta: lugar.name + detalle + " (" + lugar.country + ")"
};
msg.url = "https://api.open-meteo.com/v1/forecast?latitude=" + lugar.latitude +
    "&longitude=" + lugar.longitude +
    "&current=temperature_2m,apparent_temperature,relative_humidity_2m," +
    "weather_code,wind_speed_10m,wind_direction_10m" +
    "&daily=temperature_2m_max,temperature_2m_min&timezone=auto&forecast_days=1";
msg.requestTimeout = 6000;

node.status({ fill: "blue", shape: "ring", text: "clima de " + lugar.name });
return [null, msg];

// Traducimos el código de clima y armamos una frase simple.
const datos = msg.payload || {};
const actual = datos.current || {};
const diario = datos.daily || {};

if (msg.statusCode && msg.statusCode >= 400) {
    msg.payload = {
        output: "El servicio del clima no está disponible ahora (" +
            msg.statusCode + "). Probá de nuevo en unos minutos."
    };
    node.status({ fill: "red", shape: "dot", text: "servicio " + msg.statusCode });
    return msg;
}

if (typeof actual.temperature_2m !== "number") {
    msg.payload = { output: "No pude leer el clima de ese lugar. Probá de nuevo en unos minutos." };
    node.status({ fill: "red", shape: "dot", text: "sin datos" });
    return msg;
}

const CIELOS = {
    0: "Despejado",
    1: "Mayormente despejado",
    2: "Parcialmente nublado",
    3: "Nublado",
    45: "Niebla",
    48: "Niebla con escarcha",
    51: "Llovizna leve",
    53: "Llovizna",
    55: "Llovizna intensa",
    56: "Llovizna helada",
    57: "Llovizna helada intensa",
    61: "Lluvia leve",
    63: "Lluvia",
    65: "Lluvia intensa",
    66: "Lluvia helada",
    67: "Lluvia helada intensa",
    71: "Nieve leve",
    73: "Nieve",
    75: "Nieve intensa",
    77: "Granos de nieve",
    80: "Chubascos leves",
    81: "Chubascos",
    82: "Chubascos intensos",
    85: "Chubascos de nieve",
    86: "Chubascos de nieve intensos",
    95: "Tormenta",
    96: "Tormenta con granizo",
    99: "Tormenta con granizo intenso"
};

const DIRECCIONES = [
    "norte", "noreste", "este", "sudeste",
    "sur", "suroeste", "oeste", "noroeste"
];

function grados(n) {
    return Math.round(n) + " °C";
}

const cielo = CIELOS[actual.weather_code] || "Sin descripción";
let texto = "Clima en " + (msg._lugar ? msg._lugar.etiqueta : "ese lugar") +
    ": " + cielo + ", " + grados(actual.temperature_2m);

if (typeof actual.apparent_temperature === "number") {
    texto += " (sensación " + grados(actual.apparent_temperature) + ")";
}

if (typeof actual.relative_humidity_2m === "number") {
    texto += ". Humedad " + Math.round(actual.relative_humidity_2m) + " %";
    if (typeof actual.wind_speed_10m === "number") {
        const kmh = Math.round(actual.wind_speed_10m);
        if (kmh < 1) {
            texto += ", sin viento apreciable";
        } else {
            const indice = typeof actual.wind_direction_10m === "number"
                ? Math.round(actual.wind_direction_10m / 45) % 8
                : -1;
            texto += ", viento " + kmh + " km/h" +
                (indice >= 0 ? " del " + DIRECCIONES[indice] : "");
        }
    }
}

if (!/\.$/.test(texto)) {
    texto += ".";
}

if (Array.isArray(diario.temperature_2m_max) &&
    Array.isArray(diario.temperature_2m_min) &&
    typeof diario.temperature_2m_max[0] === "number" &&
    typeof diario.temperature_2m_min[0] === "number") {
    texto += " Hoy: máxima " + grados(diario.temperature_2m_max[0]) +
        ", mínima " + grados(diario.temperature_2m_min[0]) + ".";
}

msg.payload = { output: texto };
delete msg._busqueda;
delete msg._lugar;
node.status({ fill: "green", shape: "dot", text: "listo" });
return msg;

// Si el servicio no responde (sin internet, timeout), el usuario igual
// recibe una respuesta clara.
msg.payload = {
    output: "No pude consultar el clima en este momento. Probá de nuevo en unos minutos."
};
node.status({ fill: "red", shape: "dot", text: "sin servicio" });
return msg;
